"use client";

import Link from "next/link";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { Activity, ArrowRight, ArrowUpRight, Bell, Check, ChevronRight, Circle, CircleAlert, Clock3, Code2, Crosshair, Database, ExternalLink, FlaskConical, History, Layers3, LoaderCircle, Pause, Play, Radar, RefreshCw, Search, ShieldCheck, ShieldX, SlidersHorizontal, Terminal, Wallet, X } from "lucide-react";
import type { StmCandidate, StmDashboard, StmMutation, StmSignal, StmSource, StmStrategy, StmStrategyId } from "@/lib/stm-hunt/types";

type Tab = "terminal" | "strategies" | "sources" | "journal" | "execute";
type Json = Record<string, unknown>;
type InjectedWallet = { request: (input: { method: string; params?: unknown[] }) => Promise<unknown> };
type BscQuote = { quoteId: string; expiresAt: string | number; chainId: number; notionalUsd?: number; quotedOutput?: string; minimumOutput?: string; protectionMode?: string; approval: { token: string; spender: string; amount: string } | null; transaction: { to: string; data: string; value?: string; gas?: string }; risk?: unknown };
const strategyNames: Record<StmStrategyId, string> = { S1: "趋势确认", S2: "持续建仓", S3: "链上先手", S4: "分歧退出", S5: "拥挤过滤" };
const statusNames: Record<string, string> = { ready: "证据就绪", watch: "持续观察", blocked: "条件未满足", risk: "风险提示", ok: "可访问", stale: "数据陈旧", unavailable: "暂不可用", restricted: "需要授权", public: "公开持仓", private: "私密持仓", empty: "无公开持仓", truncated: "数据截断" };
const sourceBoards = ["fomo", "hl", "pump", "binance", "lighter", "okx"];
const money = (value: number | null | undefined, digits = 2) => value == null || !Number.isFinite(value) ? "—" : new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", maximumFractionDigits: digits }).format(value);
const compact = (value: number | null | undefined) => value == null || !Number.isFinite(value) ? "—" : new Intl.NumberFormat("en-US", { notation: "compact", maximumFractionDigits: 1 }).format(value);
const numeric = (value: number | null | undefined, digits = 2) => value == null || !Number.isFinite(value) ? "—" : value.toLocaleString("en-US", { maximumFractionDigits: digits });
const price = (value: number | null | undefined) => value == null ? "—" : money(value, value < 1 ? 8 : 4);
const shortAddress = (value: string) => value.length > 19 ? `${value.slice(0, 8)}…${value.slice(-6)}` : value;
const timeMs = (value: string | number | null | undefined) => typeof value === "number" ? value : value ? Date.parse(value) : NaN;
const rpcQuantity = (value: string) => `0x${BigInt(value).toString(16)}`;
const date = (value: string | number | null | undefined) => value && Number.isFinite(timeMs(value)) ? new Date(value).toLocaleString("zh-CN", { month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit", second: "2-digit", hour12: false }) : "时间未提供";
function record(value: unknown): Json { return value && typeof value === "object" && !Array.isArray(value) ? value as Json : {}; }
function entries(value: unknown): Json[] { return Array.isArray(value) ? value.map(record) : []; }
function text(value: unknown, fallback = "—") { return value == null ? fallback : String(value); }
async function request<T>(url: string, body?: unknown, signal?: AbortSignal): Promise<T> {
  const response = await fetch(url, { method: body ? "POST" : "GET", headers: body ? { "Content-Type": "application/json" } : undefined, body: body ? JSON.stringify(body) : undefined, cache: "no-store", signal });
  const result = await response.json().catch(() => ({ error: `服务返回 ${response.status}` }));
  if (!response.ok || result?.ok === false) throw new Error(result?.error || result?.message || `请求失败 (${response.status})`);
  return result as T;
}
function Badge({ children, tone = "muted" }: { children: React.ReactNode; tone?: string }) { return <span className={`stm-badge stm-tone-${tone}`}>{children}</span>; }
function Empty({ title, detail }: { title: string; detail: string }) { return <div className="stm-empty"><Radar size={27} /><strong>{title}</strong><p>{detail}</p></div>; }
function PanelHeading({ eyebrow, title, children }: { eyebrow: string; title: string; children?: React.ReactNode }) { return <div className="stm-panel-heading"><div><span className="stm-eyebrow">{eyebrow}</span><h2>{title}</h2></div>{children}</div>; }
function SignalBadge({ signal }: { signal?: StmSignal }) { return <Badge tone={signal?.status === "ready" ? "green" : signal?.status === "risk" ? "pink" : "yellow"}>{signal ? `${signal.strategy} · ${statusNames[signal.status]}` : "等待证据"}</Badge>; }
function SourceIndicator({ source }: { source: StmSource }) { return <div className="stm-source-row"><i className={`stm-dot stm-dot-${source.status}`} /><span>{source.name}</span><strong>{statusNames[source.status]}</strong></div>; }

export function StmHuntSurface() {
  const [data, setData] = useState<StmDashboard | null>(null);
  const [tab, setTab] = useState<Tab>("terminal");
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);
  const [search, setSearch] = useState("");
  const [filter, setFilter] = useState("all");
  const [autoRefresh, setAutoRefresh] = useState(true);
  const [board, setBoard] = useState("all");
  const [strategyId, setStrategyId] = useState<StmStrategyId>("S1");
  const [strategyDraft, setStrategyDraft] = useState<StmStrategy | null>(null);
  const [paperAmount, setPaperAmount] = useState("100");
  const [feeBps, setFeeBps] = useState("10");
  const [slippageBps, setSlippageBps] = useState("30");
  const [watchInput, setWatchInput] = useState("");
  const mounted = useRef(true);

  const load = useCallback(async (signal?: AbortSignal) => {
    try {
      const result = await request<StmDashboard>("/api/stm-hunt", undefined, signal);
      if (!signal?.aborted && mounted.current) { setData(result); setError(null); }
    } catch (caught) {
      if (!signal?.aborted && mounted.current) setError(caught instanceof Error ? caught.message : "工作台暂时无法加载");
    } finally { if (mounted.current && !signal?.aborted) setLoading(false); }
  }, []);
  useEffect(() => {
    mounted.current = true;
    const controller = new AbortController();
    void load(controller.signal);
    return () => { mounted.current = false; controller.abort(); };
  }, [load]);
  useEffect(() => {
    if (!autoRefresh) return;
    const controller = new AbortController();
    const interval = window.setInterval(() => { if (document.visibilityState === "visible") void load(controller.signal); }, 60_000);
    return () => { window.clearInterval(interval); controller.abort(); };
  }, [autoRefresh, load]);
  const mutate = async (body: StmMutation, message: string) => {
    setBusy(body.action); setError(null); setNotice(null);
    try { await request("/api/stm-hunt", body); await load(); setNotice(message); }
    catch (caught) { setError(caught instanceof Error ? caught.message : "操作失败"); }
    finally { setBusy(null); }
  };
  const candidates = useMemo(() => (data?.candidates ?? []).filter((candidate) => {
    const needle = search.trim().toLowerCase();
    const match = !needle || `${candidate.symbol} ${candidate.name} ${candidate.address ?? ""}`.toLowerCase().includes(needle);
    return match && (filter === "all" || filter === candidate.market || (filter === "watched" && data?.state.watchlist.includes(candidate.id)) || (filter === "ready" && data?.signals.some((signal) => signal.candidateId === candidate.id && signal.actionable)));
  }), [data, search, filter]);
  const selected = data?.candidates.find((candidate) => candidate.id === selectedId) ?? candidates[0] ?? null;
  const selectedSignals = data?.signals.filter((signal) => signal.candidateId === selected?.id) ?? [];
  const readySignals = data?.signals.filter((signal) => signal.actionable) ?? [];
  const sourceOk = data?.sources.filter((source) => source.status === "ok").length ?? 0;
  const unread = data?.state.alerts.filter((alert) => !alert.read).length ?? 0;
  const strategy = data?.strategies.find((item) => item.id === strategyId);
  const draft = strategyDraft?.id === strategyId && strategyDraft.version === strategy?.version ? strategyDraft : strategy;
  const traders = useMemo(() => (data?.traders ?? []).filter((trader) => (board === "all" || trader.source.toLowerCase().includes(board) || trader.venue.toLowerCase().includes(board)) && (!search || `${trader.name} ${trader.address ?? ""} ${trader.venue}`.toLowerCase().includes(search.toLowerCase()))), [data, board, search]);
  const openPaper = data?.state.paper.filter((position) => position.status === "open") ?? [];
  const closedPaper = data?.state.paper.filter((position) => position.status === "closed") ?? [];
  const tabs: { id: Tab; label: string; icon: React.ReactNode }[] = [{ id: "terminal", label: "猎手终端", icon: <Crosshair size={16} /> }, { id: "strategies", label: "策略实验室", icon: <FlaskConical size={16} /> }, { id: "sources", label: "聪明钱雷达", icon: <Radar size={16} /> }, { id: "journal", label: "模拟 · 复盘", icon: <History size={16} /> }, { id: "execute", label: "交易执行", icon: <Wallet size={16} /> }];

  return <main className="stm-page">
    <div className="stm-ambient" aria-hidden="true" />
    <div className="stm-topline"><span><i className="stm-live-dot" /> SMART MONEY INTELLIGENCE</span><span>证据驱动 · 每笔交易都有理由 <span className="stm-version">STM / v1.2.0</span></span></div>
    <header className="stm-hero">
      <div className="stm-brand"><div className="stm-mascot" aria-hidden="true"><i /><i /></div><div><div className="stm-brand-line"><h1>STM <span>hunt</span></h1><Badge tone="purple">TERMINAL</Badge></div><p>发现聪明钱，验证 Alpha，掌控每一次执行。</p><div className="stm-hero-meta"><span><i className={`stm-dot stm-dot-${data ? "ok" : "unavailable"}`} />{data ? `${sourceOk}/${data.sources.length} 数据源可访问` : "正在连接数据源"}</span><span><Clock3 size={12} />{data ? date(data.asOf) : "等待首次同步"}</span></div></div></div>
      <div className="stm-hero-actions"><Link href="/alpha-radar" className="stm-button stm-button-ghost"><ExternalLink size={14} />Alpha Radar</Link><button type="button" className="stm-button stm-button-primary" onClick={() => void mutate({ action: "refresh" }, "已完成新一轮扫描。各源更新频率以数据时间为准。")} disabled={!!busy || loading}><RefreshCw size={15} className={busy === "refresh" ? "stm-spin" : ""} />{busy === "refresh" ? "扫描中" : "扫描市场"}</button></div>
    </header>
    <section className="stm-metrics" aria-label="工作台统计">
      <div><span><Radar size={14} />追踪交易员</span><strong>{data ? numeric(data.metrics.traders, 0) : "—"}<small>IDENTITIES</small></strong><p>分平台保留身份与统计口径</p></div>
      <div><span><Crosshair size={14} />候选资产</span><strong>{data ? numeric(data.metrics.candidates, 0) : "—"}<small>ON RADAR</small></strong><p>CEX 与链上分开验证</p></div>
      <div><span><ShieldCheck size={14} />就绪信号</span><strong className="stm-green">{data ? numeric(data.metrics.ready, 0) : "—"}<small>VERIFIED</small></strong><p>缺少证据时不会放行</p></div>
      <div><span><Activity size={14} />模拟已实现盈亏</span><strong className={(data?.metrics.paperPnlUsd ?? 0) < 0 ? "stm-pink" : "stm-cyan"}>{data ? money(data.metrics.paperPnlUsd) : "—"}</strong><p>{closedPaper.length} 笔平仓 · 含设定手续费与滑点</p></div>
    </section>
    <nav className="stm-tabs" aria-label="STM hunt 功能区">{tabs.map((item) => <button key={item.id} type="button" aria-current={tab === item.id ? "page" : undefined} className={tab === item.id ? "is-active" : ""} onClick={() => { setTab(item.id); setSearch(""); }}>{item.icon}{item.label}{item.id === "journal" && unread > 0 ? <span className="stm-tab-count">{unread}</span> : null}</button>)}<button type="button" className="stm-auto-refresh" aria-pressed={autoRefresh} onClick={() => setAutoRefresh((value) => !value)} title="每分钟同步工作台，不改变上游快照频率">{autoRefresh ? <Pause size={12} /> : <Play size={12} />}{autoRefresh ? "自动同步" : "已暂停"}</button></nav>
    {error ? <div className="stm-message stm-message-error" role="alert"><CircleAlert size={17} /><span>{error}</span><button type="button" onClick={() => setError(null)} aria-label="关闭错误提示"><X size={15} /></button></div> : null}
    {notice ? <div className="stm-message stm-message-success" role="status"><Check size={17} /><span>{notice}</span><button type="button" onClick={() => setNotice(null)} aria-label="关闭提示"><X size={15} /></button></div> : null}
    {loading ? <div className="stm-loading" role="status" aria-live="polite"><LoaderCircle className="stm-spin" size={25} /><strong>初始化猎手终端</strong><span>正在核对来源、快照与策略证据…</span></div> : !data ? <Empty title="暂时无法连接终端" detail="请检查网络或使用扫描市场重试。无法获取的数据不会显示为零收益或安全。" /> : <>
      {tab === "terminal" ? <div className="stm-terminal-grid">
        <aside className="stm-agents" aria-label="六阶段执行流水线"><div className="stm-section-label"><span>AGENT PIPELINE</span><span>06 MODULES</span></div>{[
          { name: "SCANNER", label: "市场扫描", icon: <Radar />, color: "yellow", status: sourceOk ? `${data.metrics.candidates} 候选` : "等待来源", detail: "汇聚排行榜、市场与链上候选" },
          { name: "RUG CHECK", label: "风险验证", icon: <ShieldCheck />, color: "pink", status: "逐资产检查", detail: "安全未知、流动性不足时阻止链上交易" },
          { name: "SIZER", label: "仓位计算", icon: <SlidersHorizontal />, color: "purple", status: "按风险预算", detail: "先定止损，再估算仓位与交易成本" },
          { name: "EXECUTOR", label: "受控执行", icon: <Crosshair />, color: "cyan", status: "等待确认", detail: "报价、人工确认、签署、成交对账" },
          { name: "LOGGER", label: "决策审计", icon: <Code2 />, color: "orange", status: `${data.state.journal.length} 记录`, detail: "保存策略版本与每一次决策理由" },
          { name: "EQUITY", label: "收益跟踪", icon: <Activity />, color: "blue", status: `${openPaper.length} 模拟持仓`, detail: "模拟与实盘分别记录，成交后更新" },
        ].map((agent) => <div className={`stm-agent stm-tone-${agent.color}`} key={agent.name}><div className="stm-agent-icon">{agent.icon}</div><div className="stm-agent-name"><strong>{agent.name}</strong><span>{agent.label}</span></div><Badge tone={agent.color}>{agent.status}</Badge><p>{agent.detail}</p></div>)}<div className="stm-agent-note"><Terminal size={15} /><span>Observe → Verify → Execute<br /><strong>每笔交易都有理由。</strong></span></div></aside>
        <div className="stm-terminal-main">
          <section className="stm-panel stm-flow-panel"><div className="stm-flow-heading"><span className="stm-eyebrow">LIVE FLOW / 扫描 → 验证 → 风险 → 执行</span><Badge tone={readySignals.length ? "green" : "yellow"}>{readySignals.length ? "发现就绪信号" : "等待完整证据"}</Badge></div><div className="stm-flow-track"><div className="stm-flow-node stm-flow-yellow"><Radar size={24} /><strong>{data.metrics.candidates}</strong><span>扫描候选</span></div><div className="stm-flow-link"><span>规则匹配</span><i /><ArrowRight size={16} /></div><div className="stm-flow-node stm-flow-pink"><ShieldCheck size={24} /><strong>{readySignals.length}</strong><span>信号就绪</span></div><div className="stm-flow-link"><span>确认后执行</span><i /><ArrowRight size={16} /></div><div className="stm-flow-node stm-flow-cyan"><Wallet size={24} /><strong>USER</strong><span>人工确认</span></div></div><div className="stm-flow-footer"><span><i className="stm-live-dot" />{data.metrics.snapshots} 个历史快照已归档</span><button type="button" onClick={() => setTab("strategies")}>查看 S1–S5 规则 <ChevronRight size={13} /></button></div></section>
          <section className="stm-panel stm-candidates"><PanelHeading eyebrow="OPPORTUNITY RADAR" title="猎手观察池"><span className="stm-counter">{candidates.length} ASSETS</span></PanelHeading><div className="stm-table-tools"><label className="stm-search"><Search size={15} /><input aria-label="搜索候选币种或合约" placeholder="搜索代币、名称或合约地址" value={search} onChange={(event) => setSearch(event.target.value)} /></label><select aria-label="候选资产筛选" value={filter} onChange={(event) => setFilter(event.target.value)}><option value="all">全部资产</option><option value="cex">CEX 市场</option><option value="onchain">链上资产</option><option value="ready">就绪信号</option><option value="watched">我的关注</option></select></div>{candidates.length ? <div className="stm-table-scroll"><table className="stm-table"><thead><tr><th>资产 / 市场</th><th>价格 / 24h</th><th>信号与证据</th><th>来源</th><th aria-label="选择资产" /></tr></thead><tbody>{candidates.slice(0, 60).map((candidate) => { const signal = data.signals.find((item) => item.candidateId === candidate.id && item.actionable) ?? data.signals.find((item) => item.candidateId === candidate.id); return <tr key={candidate.id} className={selected?.id === candidate.id ? "is-selected" : ""} onClick={() => setSelectedId(candidate.id)}><td><button type="button" className="stm-asset-button" aria-pressed={selected?.id === candidate.id} onClick={() => setSelectedId(candidate.id)}><span className={`stm-token-icon ${candidate.market === "onchain" ? "is-chain" : ""}`}>{candidate.symbol.slice(0, 2)}</span><span><strong>{candidate.symbol}</strong><small>{candidate.chain || "BINANCE"} · {candidate.market.toUpperCase()}</small></span></button></td><td><strong className="stm-mono">{price(candidate.price)}</strong><small className={(candidate.change24h ?? 0) < 0 ? "stm-pink" : candidate.change24h == null ? "" : "stm-green"}>{candidate.change24h == null ? "24h 未提供" : `${candidate.change24h > 0 ? "+" : ""}${numeric(candidate.change24h)}%`}</small></td><td><SignalBadge signal={signal} /><small>{signal ? `${signal.entities} 实体 · ${signal.missing.length} 项待验证` : candidate.reason}</small></td><td><div className="stm-source-tags">{candidate.sources.slice(0, 2).map((source) => <span key={source}>{source}</span>)}</div></td><td><ChevronRight size={15} /></td></tr>; })}</tbody></table></div> : <Empty title="观察池暂无匹配资产" detail="等待有效来源，或调整搜索与筛选条件。" />}</section>
          <section className="stm-panel stm-log-panel"><PanelHeading eyebrow="$ tail -f stm-hunt.log" title="实时决策日志"><Badge>{data.state.journal.length} EVENTS</Badge></PanelHeading>{data.state.journal.length ? <div className="stm-log-list">{data.state.journal.slice(0, 7).map((item) => <div key={item.id}><time>{date(item.createdAt)}</time><Badge tone="cyan">{item.action}</Badge><span>{item.message}</span></div>)}</div> : <p className="stm-muted stm-padding">完成一次扫描、策略配置或模拟交易后，审计记录将在这里显示。</p>}</section>
        </div>
        <aside className="stm-detail-rail"><section className="stm-panel stm-detail"><PanelHeading eyebrow="ASSET INTELLIGENCE" title={selected ? selected.symbol : "资产证据"} />{selected ? <><div className="stm-detail-price">{price(selected.price)}<span className={(selected.change24h ?? 0) < 0 ? "stm-pink" : "stm-green"}>{selected.change24h == null ? "—" : `${selected.change24h > 0 ? "+" : ""}${numeric(selected.change24h)}%`}</span></div><p className="stm-detail-name">{selected.name} · {selected.chain || "CEX"}</p>{selected.address ? <code className="stm-contract" title={selected.address}>{selected.address}</code> : null}<div className="stm-detail-stats"><div><span>24h 成交量</span><strong>{money(selected.volumeUsd, 0)}</strong></div><div><span>池流动性</span><strong>{money(selected.liquidityUsd, 0)}</strong></div><div><span>来源持有人</span><strong>{selected.holders}</strong></div><div><span>安全状态</span><strong className={selected.risk === "pass" ? "stm-green" : "stm-yellow"}>{selected.risk === "pass" ? "通过检查" : selected.risk === "blocked" ? "已阻断" : "尚未验证"}</strong></div></div><div className="stm-evidence-list">{selectedSignals.map((signal) => <details key={signal.id} open={signal.actionable}><summary><span><b>{signal.strategy}</b> {strategyNames[signal.strategy]}</span><SignalBadge signal={signal} /></summary><p>{signal.reasons.join("；") || "尚未形成完整证据。"}</p>{signal.missing.length ? <ul>{signal.missing.map((missing) => <li key={missing}><Circle size={5} />{missing}</li>)}</ul> : null}<small>v{signal.strategyVersion} · 有效至 {date(signal.expiresAt)}</small></details>)}</div><div className="stm-detail-actions"><button type="button" className="stm-button stm-button-ghost" disabled={!!busy} onClick={() => void mutate({ action: "watch", id: selected.id, enabled: !data.state.watchlist.includes(selected.id) }, "关注列表已更新。")}><Bell size={14} />{data.state.watchlist.includes(selected.id) ? "取消关注" : "加入关注"}</button><button type="button" className="stm-button stm-button-primary" onClick={() => setTab("execute")}>交易预览 <ArrowUpRight size={14} /></button></div></> : <Empty title="选择一个资产" detail="点击观察池查看策略条件、来源与风险。" />}</section><section className="stm-panel stm-source-health"><PanelHeading eyebrow="SOURCE HEALTH" title="数据源状态"><Database size={17} /></PanelHeading>{data.sources.map((source) => <SourceIndicator key={source.id} source={source} />)}<button type="button" className="stm-text-button" onClick={() => setTab("sources")}>查看更新口径与数据明细 <ArrowRight size={13} /></button></section></aside>
      </div> : null}
      {tab === "strategies" ? <div className="stm-lab-layout"><section className="stm-panel stm-strategy-list"><PanelHeading eyebrow="STRATEGY ENGINE" title="S1–S5 策略库" />{data.strategies.map((item) => <button type="button" key={item.id} className={`stm-strategy-item ${strategyId === item.id ? "is-active" : ""}`} onClick={() => { setStrategyId(item.id); setStrategyDraft(null); }}><span>{item.id}</span><div><strong>{item.name}</strong><small>{item.description}</small></div><Badge tone={item.enabled ? "green" : "muted"}>{item.enabled ? "启用" : "停用"} · v{item.version}</Badge><ChevronRight size={15} /></button>)}<p className="stm-lab-note"><ShieldCheck size={18} />策略只使用当时已知的证据。缺失数据、时间近似与私密持仓不会被解释为买入信号。</p></section><section className="stm-panel stm-strategy-editor"><PanelHeading eyebrow={`RULE CONFIGURATION / ${strategyId}`} title={draft?.name ?? "策略参数"}><Badge tone="purple">VERSION {draft?.version ?? "—"}</Badge></PanelHeading>{draft ? <form onSubmit={(event) => { event.preventDefault(); void mutate({ action: "strategy", strategy: { id: draft.id, enabled: draft.enabled, minEntities: draft.minEntities, windowMinutes: draft.windowMinutes, minVolumeRatio: draft.minVolumeRatio, minLiquidityUsd: draft.minLiquidityUsd } }, "策略新版本已保存，后续信号将使用新参数。"); }}><p className="stm-muted">{draft.description}</p><div className="stm-form-grid"><label>独立实体数下限<input type="number" min="3" max="100" required value={draft.minEntities} onChange={(event) => setStrategyDraft({ ...draft, minEntities: Number(event.target.value) })} /></label><label>证据窗口（分钟）<input type="number" min="5" max="1440" required value={draft.windowMinutes} onChange={(event) => setStrategyDraft({ ...draft, windowMinutes: Number(event.target.value) })} /></label><label>最低成交量倍数<input type="number" min="1" max="20" step="0.1" required value={draft.minVolumeRatio} onChange={(event) => setStrategyDraft({ ...draft, minVolumeRatio: Number(event.target.value) })} /></label><label>链上最低流动性（USD）<input type="number" min="10000" max="100000000" step="1000" required value={draft.minLiquidityUsd} onChange={(event) => setStrategyDraft({ ...draft, minLiquidityUsd: Number(event.target.value) })} /></label></div><label className="stm-checkbox"><input type="checkbox" checked={draft.enabled} onChange={(event) => setStrategyDraft({ ...draft, enabled: event.target.checked })} /><span>启用该策略，参与下一轮信号评估</span></label><div className="stm-rule-explainer"><span className="stm-eyebrow">EVIDENCE REQUIREMENTS</span><p>{strategyId === "S1" ? "已收盘 15m 突破 + 成交量确认 + 准确时间的独立交易员新开/加仓。平空不会计为新多。" : strategyId === "S2" ? "固定交易员集合至少 3 次可比快照，连续两个区间的资产数量增加。价格上涨、转账、截断与私密持仓均不能证明增持。" : strategyId === "S3" ? "可验证链上 Swap、独立地址簇、持续持有、安全检查、流动性与可执行报价必须同时满足。" : strategyId === "S4" ? "在原始持仓集合中确认减仓、平仓或实际净卖出，结合价格与热度背离提示退出；不会自动建立空单。" : "按历史分位归一化资金费率，以持仓数量而非美元估值判断 OI，识别资金费率、持仓量与价格共同上涨的拥挤风险；不可用指标只显示未知。"}</p></div><button type="submit" className="stm-button stm-button-primary" disabled={!!busy}><Layers3 size={15} />{busy === "strategy" ? "保存中…" : "保存为新版本"}</button></form> : null}<div className="stm-strategy-results"><h3>当前评估结果</h3>{data.signals.filter((signal) => signal.strategy === strategyId).length ? data.signals.filter((signal) => signal.strategy === strategyId).slice(0, 12).map((signal) => <div key={signal.id}><strong>{signal.symbol}</strong><SignalBadge signal={signal} /><span>{signal.missing[0] || signal.reasons[0]}</span></div>) : <p className="stm-muted">暂无可评估资产，先执行市场扫描。</p>}</div></section></div> : null}
      {tab === "sources" ? <><section className="stm-board-grid">{sourceBoards.map((id) => { const source = data.sources.find((item) => item.id.toLowerCase().includes(id)); return <button type="button" key={id} className={`stm-panel stm-board-card ${board === id ? "is-active" : ""}`} onClick={() => setBoard(board === id ? "all" : id)}><span className="stm-eyebrow">WEB3 SMART MONEY</span><div><h2>{id === "hl" ? "HYPERLIQUID" : id.toUpperCase()}</h2><ArrowUpRight size={18} /></div><strong>{source ? source.count : "—"}<small>交易员 / 记录</small></strong><Badge tone={source?.status === "ok" ? "green" : "yellow"}>{source ? statusNames[source.status] : "等待来源"}</Badge><p>{source?.message || "数据源未连接，暂无可用快照。"}</p></button>; })}</section><section className="stm-panel stm-traders"><PanelHeading eyebrow="TRADER INTELLIGENCE" title="聪明钱身份与持仓"><Badge>{traders.length} IDENTITIES</Badge></PanelHeading><div className="stm-table-tools"><label className="stm-search"><Search size={15} /><input aria-label="搜索交易员" value={search} onChange={(event) => setSearch(event.target.value)} placeholder="搜索交易员、平台或钱包地址" /></label><select aria-label="数据源筛选" value={board} onChange={(event) => setBoard(event.target.value)}><option value="all">全部数据源</option>{sourceBoards.map((id) => <option key={id} value={id}>{id.toUpperCase()}</option>)}<option value="traderadar">Top Trader Radar</option></select></div>{traders.length ? <div className="stm-table-scroll"><table className="stm-table"><thead><tr><th>交易员 / 唯一身份</th><th>来源</th><th>盈亏 / 统计窗口</th><th>ROI / 胜率</th><th>持仓可见性</th><th>关注</th></tr></thead><tbody>{traders.slice(0, 100).map((trader) => <tr key={trader.id}><td><strong>{trader.name}</strong><small title={trader.address || trader.id}>{shortAddress(trader.address || trader.id)}</small></td><td><Badge tone="purple">{trader.venue}</Badge><small>{date(trader.updatedAt)}</small></td><td><strong className={trader.pnlUsd == null ? "" : trader.pnlUsd < 0 ? "stm-pink" : "stm-green"}>{money(trader.pnlUsd)}</strong><small>{trader.pnlWindow || "统计窗口未提供"}</small></td><td><strong>{trader.roi == null ? "—" : `${numeric(trader.roi)}%`}</strong><small>胜率 {trader.winRate == null ? "未知" : `${numeric(trader.winRate)}%`}</small></td><td><Badge tone={trader.visibility === "public" ? "cyan" : "yellow"}>{statusNames[trader.visibility]}</Badge><details className="stm-holdings"><summary>{trader.holdings.length} 条持仓记录</summary>{trader.holdings.slice(0, 12).map((holding, index) => <div key={`${holding.asset}-${index}`}><b>{holding.symbol}</b><span>{holding.side} · {holding.quantity == null ? "数量未知" : numeric(holding.quantity, 6)}</span><span>{money(holding.valueUsd)}</span></div>)}</details></td><td><button type="button" className={`stm-icon-button ${data.state.watchlist.includes(trader.id) ? "is-active" : ""}`} aria-label={`${data.state.watchlist.includes(trader.id) ? "取消关注" : "关注"}${trader.name}`} disabled={!!busy} onClick={() => void mutate({ action: "watch", id: trader.id, enabled: !data.state.watchlist.includes(trader.id) }, "交易员关注已更新。")}><Bell size={15} /></button></td></tr>)}</tbody></table>{traders.length > 100 ? <p className="stm-muted stm-padding">显示前 100 条，使用来源与名称筛选继续查找。</p> : null}</div> : <Empty title="该来源暂无可用身份" detail="数据访问受限或源快照不可用时，将保留状态说明。" />}</section><section className="stm-panel stm-source-details"><PanelHeading eyebrow="DATA PROVENANCE" title="来源、时效与数据口径" /><div className="stm-provenance-grid">{data.sources.map((source) => <article key={source.id}><div><h3>{source.name}</h3><Badge tone={source.status === "ok" ? "green" : "yellow"}>{statusNames[source.status]}</Badge></div><p>{source.message}</p><dl><dt>数据语义</dt><dd>{source.semantics === "snapshot" ? "持仓快照" : source.semantics === "events" ? "交易事件" : source.semantics === "market" ? "市场行情" : "上下文参考"}</dd><dt>数据时间</dt><dd>{date(source.updatedAt)}</dd><dt>获取时间</dt><dd>{date(source.fetchedAt)}</dd></dl><a href={source.url} target="_blank" rel="noreferrer">原始来源 <ExternalLink size={12} /></a></article>)}</div><div className="stm-capability-notes"><h3>接入能力与待补证据</h3>{data.capabilities.notes.map((note) => <p key={note}><CircleAlert size={13} />{note}</p>)}<p><Code2 size={13} />链上解码事件接收：<code>/api/stm-hunt/ingest</code>。仅接受已配置签名且通过链上交易核验的事件。</p></div><p className="stm-source-disclaimer">不同平台的收益窗口、公开范围与更新周期不同，不做跨平台收益排名。快照差值代表仓位变化，不等同于实时成交。TopTrader 受限事件仅在授权后使用。</p></section></> : null}
      {tab === "journal" ? <div className="stm-journal-layout"><div><section className="stm-panel stm-paper"><PanelHeading eyebrow="PAPER TRADING" title="模拟交易账本"><Badge tone="purple">独立模拟资金</Badge></PanelHeading><form className="stm-paper-form" onSubmit={(event) => { event.preventDefault(); if (selected) void mutate({ action: "paper-open", candidateId: selected.id, strategy: strategyId, notionalUsd: Number(paperAmount), feeBps: Number(feeBps), slippageBps: Number(slippageBps), idempotencyKey: crypto.randomUUID() }, "模拟订单已创建，手续费与滑点已计入。"); }}><label>候选资产<select value={selected?.id ?? ""} onChange={(event) => setSelectedId(event.target.value)} required><option value="" disabled>选择资产</option>{data.candidates.map((candidate) => <option key={candidate.id} value={candidate.id}>{candidate.symbol} · {candidate.chain || "CEX"}</option>)}</select></label><label>策略<select value={strategyId} onChange={(event) => setStrategyId(event.target.value as StmStrategyId)}>{data.strategies.map((item) => <option key={item.id} value={item.id}>{item.id} {item.name}</option>)}</select></label><label>名义金额（USD）<input type="number" min="10" max="10000" value={paperAmount} required onChange={(event) => setPaperAmount(event.target.value)} /></label><label>手续费（bps）<input type="number" min="0" max="500" value={feeBps} required onChange={(event) => setFeeBps(event.target.value)} /></label><label>滑点（bps）<input type="number" min="0" max="500" value={slippageBps} required onChange={(event) => setSlippageBps(event.target.value)} /></label><button type="submit" className="stm-button stm-button-primary" disabled={!selected || !!busy}><FlaskConical size={14} />记录模拟开仓</button></form><div className="stm-table-scroll">{data.state.paper.length ? <table className="stm-table"><thead><tr><th>资产 / 策略</th><th>入场 / 出场</th><th>金额 / 数量</th><th>已实现盈亏</th><th>操作</th></tr></thead><tbody>{data.state.paper.map((position) => <tr key={position.id}><td><strong>{position.symbol}</strong><small>{position.strategy} · {position.status === "open" ? "持仓中" : "已平仓"}</small></td><td><strong>{price(position.entryPrice)}</strong><small>{position.exitPrice == null ? "等待平仓" : price(position.exitPrice)}</small></td><td><strong>{money(position.notionalUsd)}</strong><small>{numeric(position.quantity, 6)}</small></td><td className={(position.pnlUsd ?? 0) < 0 ? "stm-pink" : "stm-green"}>{money(position.pnlUsd)}</td><td>{position.status === "open" ? <button type="button" className="stm-button stm-button-small" disabled={!!busy} onClick={() => void mutate({ action: "paper-close", id: position.id }, "模拟仓位已按最新可用价格平仓。")}>平仓</button> : <span className="stm-muted">{date(position.closedAt)}</span>}</td></tr>)}</tbody></table> : <Empty title="还没有模拟交易" detail="从真实候选资产记录第一笔模拟仓位。这里的收益不会计入实盘。" />}</div></section><section className="stm-panel stm-replay"><PanelHeading eyebrow="POINT-IN-TIME REPLAY" title="历史证据复盘"><History size={17} /></PanelHeading><p className="stm-muted">按归档快照和当时的证据重放 S1–S5。没有完整成交与可执行历史价格时，不输出虚构回测收益。</p><button type="button" className="stm-button stm-button-ghost" disabled={!!busy || !data.metrics.snapshots} onClick={() => void mutate({ action: "replay", feeBps: Number(feeBps), slippageBps: Number(slippageBps) }, "历史证据重放已完成。")}>{busy === "replay" ? <LoaderCircle size={15} className="stm-spin" /> : <Play size={15} />}运行复盘</button>{data.state.replays.map((replay) => <article key={replay.id}><div><strong>{date(replay.createdAt)}</strong><Badge tone="cyan">{replay.snapshots} 快照</Badge><Badge>{replay.ready}/{replay.signals} 就绪</Badge></div><p>{replay.message}</p>{replay.performance ? <div className="stm-replay-metrics"><span>净收益 <strong className={replay.performance.netPnlUsd < 0 ? "stm-pink" : "stm-green"}>{money(replay.performance.netPnlUsd)} ({numeric(replay.returns)}%)</strong></span><span>模拟交易 <strong>{replay.performance.trades}</strong></span><span>胜率 <strong>{numeric(replay.performance.winRate)}%</strong></span><span>最大回撤 <strong>{numeric(replay.performance.maxDrawdownPct)}%</strong></span></div> : null}<small>{date(replay.start)} → {date(replay.end)} · 费率 {replay.feeBps} bps / 滑点 {replay.slippageBps} bps</small></article>)}</section></div><div><WalletGroups /><section className="stm-panel stm-watchlist"><PanelHeading eyebrow="MY WATCHLIST" title="关注与预警"><Bell size={17} /></PanelHeading><form onSubmit={(event) => { event.preventDefault(); if (watchInput.trim()) { void mutate({ action: "watch", id: watchInput.trim(), enabled: true }, "关注已添加。"); setWatchInput(""); } }}><label className="stm-search"><input aria-label="关注候选或交易员标识" value={watchInput} maxLength={200} onChange={(event) => setWatchInput(event.target.value)} placeholder="资产 / 交易员完整标识" /></label><button type="submit" className="stm-button stm-button-small" disabled={!!busy || !watchInput.trim()}>添加</button></form><div className="stm-watch-items">{data.state.watchlist.map((id) => <div key={id}><span title={id}>{data.candidates.find((candidate) => candidate.id === id)?.symbol || data.traders.find((trader) => trader.id === id)?.name || shortAddress(id)}</span><button type="button" aria-label={`取消关注 ${id}`} disabled={!!busy} onClick={() => void mutate({ action: "watch", id, enabled: false }, "已移除关注。")}><X size={13} /></button></div>)}</div>{!data.state.watchlist.length ? <p className="stm-muted">在资产与交易员旁点击铃铛，即可加入关注列表。</p> : null}<div className="stm-alerts">{data.state.alerts.length ? data.state.alerts.slice(0, 30).map((alert) => <button type="button" key={alert.id} className={alert.read ? "is-read" : ""} disabled={!!busy} onClick={() => void mutate({ action: "alert-read", id: alert.id }, "预警已标记为已读。")}><span><Badge tone="yellow">{alert.strategy}</Badge><strong>{alert.symbol}</strong>{!alert.read ? <i className="stm-live-dot" /> : null}</span><p>{alert.message}</p><time>{date(alert.createdAt)}</time></button>) : <Empty title="暂无预警" detail="关注资产出现符合条件的信号时，预警会留在这里。" />}</div></section><section className="stm-panel stm-audit"><PanelHeading eyebrow="AUDIT TRAIL" title="操作记录" /><div className="stm-audit-list">{data.state.journal.slice(0, 30).map((item) => <div key={item.id}><span><Badge>{item.action}</Badge><time>{date(item.createdAt)}</time></span><p>{item.message}</p></div>)}</div></section></div></div> : null}
      {tab === "execute" ? <ExecutionPanel selected={selected} candidates={data.candidates} onSelect={setSelectedId} /> : null}
      <div className="stm-delivery-bar"><span><Layers3 size={14} /> v1.0 数据研究 <i>→</i> v1.1 策略复盘 <i>→</i> v1.2 受控实盘</span><div><a className="stm-button stm-button-small stm-button-ghost" href="/api/stm-hunt/export?format=json" download>导出 JSON</a><a className="stm-button stm-button-small stm-button-ghost" href="/api/stm-hunt/export?format=csv" download>导出 CSV</a></div></div><footer className="stm-footer"><span><Terminal size={13} />STM hunt · 证据优先，执行可追溯。</span><span>{!data.state.authenticated ? "未登录，私人操作需登录" : data.state.persistent ? "持久化存储已连接" : "持久化不可用，写入功能将被阻止"} <i />行情与榜单遵循各来源更新周期</span></footer>
    </>}
  </main>;
}

function ExecutionPanel({ selected, candidates, onSelect }: { selected: StmCandidate | null; candidates: StmCandidate[]; onSelect: (id: string) => void }) {
  const [venue, setVenue] = useState<"cex" | "bsc">(selected?.market === "onchain" ? "bsc" : "cex");
  const [overview, setOverview] = useState<Json | null>(null);
  const [mode, setMode] = useState("paper");
  const [market, setMarket] = useState("spot");
  const [symbol, setSymbol] = useState(selected?.symbol.replace(/\/?USDT$/, "") ? `${selected.symbol.replace(/\/?USDT$/, "")}USDT` : "BTCUSDT");
  const [side, setSide] = useState("LONG");
  const [entry, setEntry] = useState(selected?.price?.toString() ?? "");
  const [stop, setStop] = useState("");
  const [take, setTake] = useState("");
  const [risk, setRisk] = useState("0.5");
  const [leverage, setLeverage] = useState("1");
  const [strategy, setStrategy] = useState("S1");
  const [address, setAddress] = useState("");
  const [token, setToken] = useState(selected?.address ?? "");
  const [payToken, setPayToken] = useState("USDT");
  const [amount, setAmount] = useState("");
  const [slippage, setSlippage] = useState("50");
  const [stopPct, setStopPct] = useState("10");
  const [takePct, setTakePct] = useState("30");
  const [buySell, setBuySell] = useState("buy");
  const [busy, setBusy] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [message, setMessage] = useState<string | null>(null);
  const [plan, setPlan] = useState<Json | null>(null);
  const [quote, setQuote] = useState<BscQuote | null>(null);
  const [riskResult, setRiskResult] = useState<Json | null>(null);
  const [confirmed, setConfirmed] = useState(false);
  const [txHash, setTxHash] = useState<string | null>(null);
  const [activeQuote, setActiveQuote] = useState<string | null>(null);
  const executionMounted = useRef(true);
  useEffect(() => { executionMounted.current = true; return () => { executionMounted.current = false; }; }, []);
  const refresh = useCallback(async (signal?: AbortSignal) => { const result = await request<Json>("/api/stm-hunt/trade", undefined, signal); setOverview(result); }, []);
  useEffect(() => { const controller = new AbortController(); void refresh(controller.signal).catch((caught) => { if (!controller.signal.aborted) setError(caught instanceof Error ? caught.message : "交易账户暂不可用"); }); return () => controller.abort(); }, [refresh]);
  const run = async (name: string, fn: () => Promise<void>) => { setBusy(name); setError(null); setMessage(null); try { await fn(); } catch (caught) { setError(caught instanceof Error ? caught.message : "交易操作失败"); } finally { setBusy(null); } };
  const invalidate = () => { setPlan(null); setQuote(null); setConfirmed(false); };
  const wallets = entries(overview?.wallets).filter((wallet) => wallet.chain === "EVM" || wallet.chain === "bsc");
  const cex = record(overview?.cex);
  const credentials = entries(cex.credentials);
  const config = record(cex.config);
  const spotLiveBlocked = venue === "cex" && mode === "live" && market === "spot";
  const provider = () => { const wallet = (window as Window & { ethereum?: InjectedWallet }).ethereum; if (!wallet) throw new Error("未检测到浏览器 EVM 钱包。请安装钱包并先在账户设置中完成所有权绑定。"); return wallet; };
  const connect = async () => { const accounts = await provider().request({ method: "eth_requestAccounts" }) as string[]; if (!accounts[0]) throw new Error("钱包没有返回可用地址。"); setAddress(accounts[0]); invalidate(); };
  const submitBsc = async () => {
    if (!quote || !confirmed) throw new Error("请先审阅并确认当前报价。");
    if (Date.now() >= timeMs(quote.expiresAt)) { setQuote(null); throw new Error("报价已过期，请重新获取报价。"); }
    const wallet = provider();
    const accounts = await wallet.request({ method: "eth_accounts" }) as string[];
    if (!accounts.some((account) => account.toLowerCase() === address.toLowerCase())) throw new Error("当前钱包账户与报价地址不一致。");
    await wallet.request({ method: "wallet_switchEthereumChain", params: [{ chainId: "0x38" }] });
    if (String(await wallet.request({ method: "eth_chainId" })).toLowerCase() !== "0x38") throw new Error("钱包未切换至 BNB Smart Chain。");
    if (quote.approval) {
      const { encodeFunctionData, erc20Abi } = await import("viem");
      const approvalHash = await wallet.request({ method: "eth_sendTransaction", params: [{ chainId: "0x38", from: address, to: quote.approval.token, data: encodeFunctionData({ abi: erc20Abi, functionName: "approve", args: [quote.approval.spender as `0x${string}`, BigInt(quote.approval.amount)] }) }] }) as string;
      setMessage(`精确额度授权已提交 ${shortAddress(approvalHash)}，正在等待链上确认。`);
      let confirmedApproval = false;
      for (let attempt = 0; attempt < 60; attempt += 1) {
        if (!executionMounted.current) throw new Error("已离开交易页面，未继续发送 Swap。请在钱包核对授权状态。");
        const receipt = await wallet.request({ method: "eth_getTransactionReceipt", params: [approvalHash] }) as { status?: string } | null;
        if (receipt) { if (receipt.status !== "0x1") throw new Error("代币授权交易失败，未发送 Swap。"); confirmedApproval = true; break; }
        await new Promise((resolve) => window.setTimeout(resolve, 2_000));
      }
      if (!confirmedApproval) throw new Error("授权仍在确认中。请查看钱包后重新获取报价，不要重复提交授权。");
    }
    if (Date.now() >= timeMs(quote.expiresAt)) { setQuote(null); throw new Error("授权完成，原报价已过期。请重新获取报价后签署 Swap。"); }
    if (!executionMounted.current) throw new Error("已离开交易页面，未发送 Swap。");
    const validation = await request<{ transaction: BscQuote["transaction"] }>("/api/stm-hunt/trade", { action: "validate-quote", quoteId: quote.quoteId, address });
    if (!executionMounted.current) throw new Error("已离开交易页面，未发送 Swap。");
    const [finalAccounts, finalChain] = await Promise.all([
      wallet.request({ method: "eth_accounts" }) as Promise<string[]>,
      wallet.request({ method: "eth_chainId" })
    ]);
    if (String(finalChain).toLowerCase() !== "0x38") throw new Error("签署前钱包链已变化，未发送 Swap；请切回 BNB Smart Chain 后重新报价。");
    if (!finalAccounts.some((account) => account.toLowerCase() === address.toLowerCase())) throw new Error("签署前已验证的钱包账户不可用，未发送 Swap。");
    if (!executionMounted.current || Date.now() + 5_000 >= timeMs(quote.expiresAt)) throw new Error("签署前报价即将过期或页面已离开，未发送 Swap；请重新报价。");
    const transaction = validation.transaction;
    const hash = await wallet.request({ method: "eth_sendTransaction", params: [{ chainId: "0x38", from: address, to: transaction.to, data: transaction.data, value: rpcQuantity(transaction.value || "0"), ...(transaction.gas ? { gas: rpcQuantity(transaction.gas) } : {}) }] }) as string;
    setTxHash(hash); setActiveQuote(quote.quoteId); setQuote(null); setConfirmed(false);
    try { await request("/api/stm-hunt/trade", { action: "submit", quoteId: quote.quoteId, address, txHash: hash, confirmation: "CONFIRM_STM_BSC_TRADE" }); setMessage("交易已广播并记录。请执行成交对账，确认最终状态。"); }
    catch (caught) { throw new Error(`交易已广播 ${hash}，登记暂未完成：${caught instanceof Error ? caught.message : "请重试对账"}。请勿重复交易。`); }
    await refresh();
  };
  return <div className="stm-execution-layout"><section className="stm-panel stm-order-form"><PanelHeading eyebrow="CONTROLLED EXECUTION" title="交易执行工作台"><Badge tone={mode === "live" || venue === "bsc" ? "pink" : "purple"}>{venue === "bsc" ? "BSC MAINNET" : mode === "live" ? "LIVE MODE" : "PAPER MODE"}</Badge></PanelHeading><div className="stm-venue-tabs"><button type="button" className={venue === "cex" ? "is-active" : ""} disabled={!!busy} onClick={() => { setVenue("cex"); invalidate(); }}>Binance CEX</button><button type="button" className={venue === "bsc" ? "is-active" : ""} disabled={!!busy} onClick={() => { setVenue("bsc"); invalidate(); }}>BSC 钱包 / DEX</button><span>Solana 执行待接入</span></div>{error ? <div className="stm-message stm-message-error" role="alert"><CircleAlert size={16} /><span>{error}</span></div> : null}{message ? <div className="stm-message stm-message-success" role="status"><Check size={16} /><span>{message}</span></div> : null}<div className="stm-execution-note"><ShieldCheck size={18} /><p>实盘沿用账户授权、管理员 2FA、执行开关与额度限制。获取预览不会下单，只有审阅后确认才会执行。{venue === "cex" && mode === "live" ? <><br /><strong>CEX 实盘仅执行当前策略已就绪的做多信号；S5 必须启用且证据正常，研究状态或未知证据不会放行。</strong></> : null}</p></div><label className="stm-wide-field">从观察池填入资产<select disabled={!!busy} value={selected?.id ?? ""} onChange={(event) => { const item = candidates.find((candidate) => candidate.id === event.target.value); onSelect(event.target.value); if (item) { setSymbol(`${item.symbol.replace(/\/?USDT$/, "")}USDT`); setEntry(item.price?.toString() ?? ""); setToken(item.address ?? ""); invalidate(); } }}><option value="">选择候选资产</option>{candidates.map((candidate) => <option key={candidate.id} value={candidate.id}>{candidate.symbol} · {candidate.chain || "CEX"}</option>)}</select></label>{venue === "cex" ? <form onSubmit={(event) => { event.preventDefault(); void run("intent", async () => { const result = await request<Json>("/api/stm-hunt/trade", { action: "intent", venue: "cex", mode, market, symbol, side, entryPrice: Number(entry), stopLoss: Number(stop), takeProfit: Number(take), leverage: Number(leverage), riskPct: Number(risk), strategy, requestId: crypto.randomUUID(), alphaScore: selected?.score }); setPlan(result); setConfirmed(false); setMessage("执行计划已生成。请核对仓位、止损与费用，再确认执行。"); await refresh(); }); }}><div className="stm-form-grid"><label>执行模式<select disabled={!!busy} value={mode} onChange={(event) => { setMode(event.target.value); invalidate(); }}><option value="paper">模拟交易</option><option value="live">实盘交易</option></select></label><label>市场<select disabled={!!busy} value={market} onChange={(event) => { setMarket(event.target.value); if (event.target.value === "spot") setSide("LONG"); invalidate(); }}><option value="spot">现货 Spot</option><option value="futures">USDT 永续</option></select></label><label>交易对<input disabled={!!busy} required value={symbol} pattern="[A-Z0-9]{5,30}" onChange={(event) => { setSymbol(event.target.value.toUpperCase()); invalidate(); }} placeholder="BTCUSDT" /></label><label>方向<select disabled={!!busy} value={side} onChange={(event) => { setSide(event.target.value); invalidate(); }}><option value="LONG">做多 / 买入</option>{market === "futures" ? <option value="SHORT">做空</option> : null}</select></label><label>参考入场价<input disabled={!!busy} type="number" min="0.000000001" step="any" required value={entry} onChange={(event) => { setEntry(event.target.value); invalidate(); }} /></label><label>止损价<input disabled={!!busy} type="number" min="0.000000001" step="any" required value={stop} onChange={(event) => { setStop(event.target.value); invalidate(); }} /></label><label>止盈价<input disabled={!!busy} type="number" min="0.000000001" step="any" required value={take} onChange={(event) => { setTake(event.target.value); invalidate(); }} /></label><label>单笔风险预算（%）<input disabled={!!busy} type="number" min="0.1" max="1.5" step="0.1" required value={risk} onChange={(event) => { setRisk(event.target.value); invalidate(); }} /></label><label>杠杆<input disabled={!!busy} type="number" min="1" max={market === "spot" ? "1" : "20"} required value={leverage} onChange={(event) => { setLeverage(event.target.value); invalidate(); }} /></label><label>策略归因<select disabled={!!busy} value={strategy} onChange={(event) => { setStrategy(event.target.value); invalidate(); }}>{Object.entries(strategyNames).filter(([id]) => !["S4", "S5"].includes(id)).map(([id, label]) => <option key={id} value={id}>{id} {label}</option>)}</select></label></div>{spotLiveBlocked ? <p className="stm-live-spot-note"><CircleAlert size={14} />STM 当前实盘支持 USDT 永续。现货成本与转账历史尚未完成核算，现货仅开放模拟，请手动选择永续市场后继续。</p> : null}<div className="stm-form-actions"><button type="button" className="stm-button stm-button-ghost" disabled={!!busy} onClick={() => void run("preflight", async () => { const result = await request<Json>("/api/stm-hunt/trade", { action: "preflight", mode, market }); setMessage(text(result.message, "预检完成，请核对下方账户与执行状态。")); await refresh(); })}><ShieldCheck size={14} />实盘账户预检</button><button type="submit" className="stm-button stm-button-primary" disabled={!!busy || spotLiveBlocked}><SlidersHorizontal size={15} />{busy === "intent" ? "计算中…" : "生成执行计划"}</button></div></form> : <form onSubmit={(event) => { event.preventDefault(); void run("quote", async () => { const result = await request<BscQuote>("/api/stm-hunt/trade", { action: "quote", venue: "bsc", address, tokenAddress: token, side: buySell, payToken, amount, slippageBps: Number(slippage), stopLossPct: Number(stopPct), takeProfitPct: Number(takePct), requestId: crypto.randomUUID() }); setQuote(result); setActiveQuote(result.quoteId); setConfirmed(false); setMessage("报价已获取。请核对链、路由、授权额度与有效期。"); }); }}><div className="stm-wallet-connect"><Wallet size={17} /><span>{address ? shortAddress(address) : "尚未选择浏览器钱包"}</span><button type="button" className="stm-button stm-button-small" disabled={!!busy} onClick={() => void run("connect", connect)}>连接钱包</button></div><div className="stm-form-grid"><label className="stm-field-full">已绑定地址<input disabled={!!busy} value={address} placeholder="0x…（需先完成本站所有权绑定）" required pattern="0x[0-9a-fA-F]{40}" onChange={(event) => { setAddress(event.target.value); invalidate(); }} list="stm-wallets" /><datalist id="stm-wallets">{wallets.map((wallet) => <option key={text(wallet.address)} value={text(wallet.address)} />)}</datalist></label><label className="stm-field-full">BNB Chain 代币合约<input disabled={!!busy} value={token} required pattern="0x[0-9a-fA-F]{40}" placeholder="0x…" onChange={(event) => { setToken(event.target.value); setRiskResult(null); invalidate(); }} /></label><label>方向<select disabled={!!busy} value={buySell} onChange={(event) => { setBuySell(event.target.value); invalidate(); }}><option value="buy">买入代币</option><option value="sell">卖出代币</option></select></label><label>支付 / 接收币种<select disabled={!!busy} value={payToken} onChange={(event) => { setPayToken(event.target.value); invalidate(); }}><option>USDT</option><option>USDC</option></select></label><label>{buySell === "buy" ? "支付金额（稳定币）" : "卖出数量（代币）"}<input disabled={!!busy} type="number" min="0.00000001" step="any" required value={amount} onChange={(event) => { setAmount(event.target.value); invalidate(); }} /></label><label>最大滑点（bps）<input disabled={!!busy} type="number" min="10" max="100" required value={slippage} onChange={(event) => { setSlippage(event.target.value); invalidate(); }} /></label><label>止损参考（%）<input disabled={!!busy} type="number" min="1" max="30" required value={stopPct} onChange={(event) => { setStopPct(event.target.value); invalidate(); }} /></label><label>止盈参考（%）<input disabled={!!busy} type="number" min="1" max="300" required value={takePct} onChange={(event) => { setTakePct(event.target.value); invalidate(); }} /></label></div><p className="stm-muted">链上止盈止损是风控参考，当前 Swap 不会自动挂出条件单。请持续监控仓位。</p><div className="stm-form-actions"><button type="button" className="stm-button stm-button-ghost" disabled={!!busy || !/^0x[0-9a-fA-F]{40}$/.test(token)} onClick={() => void run("risk", async () => { const result = await request<Json>(`/api/stm-hunt/risk?chain=bsc&address=${encodeURIComponent(token)}`); setRiskResult(record(result.risk)); })}><ShieldCheck size={15} />安全与流动性检查</button><button type="submit" className="stm-button stm-button-primary" disabled={!!busy}><ArrowRight size={15} />获取可执行报价</button></div></form>}{riskResult ? <div className="stm-risk-result"><Badge tone={riskResult.eligible ? "green" : "pink"}>{text(riskResult.status)} · {riskResult.eligible ? "通过当前检查" : "禁止执行"}</Badge><p>{Array.isArray(riskResult.reasons) ? riskResult.reasons.join("；") : "查看风险检查结果。"}</p><span>流动性 {money(typeof riskResult.liquidityUsd === "number" ? riskResult.liquidityUsd : null)}</span></div> : null}{plan || quote ? <div className="stm-confirm-panel"><div className="stm-section-label"><span>REVIEW BEFORE EXECUTION</span><ShieldCheck size={16} /></div>{plan ? <><h3>CEX 执行计划</h3><PlanDetails plan={plan} /></> : quote ? <><h3>BSC 链上报价</h3><dl><dt>链 / 接收钱包</dt><dd>BNB Smart Chain (56) / {shortAddress(address)}</dd><dt>名义金额</dt><dd>{money(quote.notionalUsd)}</dd><dt>预期 / 最低输出</dt><dd>{quote.quotedOutput ?? "—"} / {quote.minimumOutput ?? "—"}</dd><dt>交易合约</dt><dd>{quote.transaction.to}</dd><dt>报价有效至</dt><dd>{date(quote.expiresAt)}</dd><dt>精确授权</dt><dd>{quote.approval ? `${quote.approval.amount} 原始单位 → ${quote.approval.spender}` : "无需额外授权"}</dd></dl></> : null}{plan ? <button type="button" className="stm-button stm-button-small stm-button-ghost" disabled={!!busy} onClick={() => void run("cancel", async () => { await request("/api/stm-hunt/trade", { action: "cancel", planId: plan.planId ?? record(plan.executionPlan).planId }); setPlan(null); setConfirmed(false); setMessage("待确认计划已取消，未下单。"); await refresh(); })}>取消此执行计划</button> : null}<label className="stm-checkbox"><input disabled={!!busy} type="checkbox" checked={confirmed} onChange={(event) => setConfirmed(event.target.checked)} /><span>我已核对当前计划、资金金额、止损与费用，并确认{venue === "bsc" || mode === "live" ? "使用真实资金执行此笔交易" : "执行此笔模拟交易"}。</span></label><button type="button" className={`stm-button ${venue === "bsc" || mode === "live" ? "stm-button-danger" : "stm-button-primary"}`} disabled={!!busy || !confirmed} onClick={() => void run("execute", async () => { if (venue === "bsc") { await submitBsc(); } else { await request("/api/stm-hunt/trade", { action: "execute", planId: plan?.planId ?? record(plan?.plan).id, confirmation: "EXECUTE_APPROVED_PLAN" }); setPlan(null); setConfirmed(false); setMessage("执行请求已完成，请在订单与对账记录中核对最终状态。"); await refresh(); } })}>{busy === "execute" ? <LoaderCircle className="stm-spin" size={15} /> : <Wallet size={15} />}{venue === "bsc" ? "签署精确授权与 Swap" : mode === "live" ? "确认执行实盘计划" : "确认执行模拟计划"}</button></div> : null}{txHash ? <div className="stm-tx-result"><strong>已广播交易</strong><a href={`https://bscscan.com/tx/${txHash}`} target="_blank" rel="noreferrer">{shortAddress(txHash)} <ExternalLink size={12} /></a><button type="button" className="stm-button stm-button-small" disabled={!!busy || !activeQuote} onClick={() => void run("reconcile-bsc", async () => { const result = await request<Json>("/api/stm-hunt/trade", { action: "reconcile", venue: "bsc", quoteId: activeQuote, address }); setMessage(text(result.message, "链上状态已重新核对。")); await refresh(); })}>链上成交对账</button></div> : null}</section><aside><section className="stm-panel stm-execution-status"><PanelHeading eyebrow="EXECUTION GUARDRAILS" title="账户与执行状态" /><div className="stm-account-status"><span>CEX 凭据</span><Badge tone={credentials.length ? "cyan" : "yellow"}>{overview ? credentials.length ? `${credentials.length} 已配置` : "尚未配置" : "等待账户验证"}</Badge></div><div className="stm-account-status"><span>已绑定钱包</span><Badge tone={wallets.length ? "cyan" : "yellow"}>{overview ? `${wallets.length} 地址` : "等待账户验证"}</Badge></div><div className="stm-account-status"><span>执行模式</span><Badge tone={mode === "live" || venue === "bsc" ? "pink" : "purple"}>{venue === "bsc" ? "用户钱包签署" : mode === "live" ? "实盘需管理员与 2FA" : "模拟执行"}</Badge></div><div className="stm-account-status"><span>实盘解锁</span><Badge tone={config.liveEnabled && config.liveUnlockedAt ? "cyan" : "yellow"}>{!overview ? "等待服务端校验" : config.liveEnabled && config.liveUnlockedAt ? "账户已解锁" : "需在执行中心独立解锁"}</Badge></div><div className="stm-account-status"><span>紧急停机</span><Badge tone={config.killSwitch || config.killSwitchActive ? "pink" : "muted"}>{config.killSwitch || config.killSwitchActive ? "已开启" : "以服务端检查为准"}</Badge></div><div className="stm-setup-links"><Link href="/alpha-radar#execution-control">管理 Binance 凭据 <ExternalLink size={12} /></Link><Link href="/account/connections">绑定钱包 <ExternalLink size={12} /></Link><Link href="/account/security">管理 2FA 安全设置 <ExternalLink size={12} /></Link></div><button type="button" className="stm-button stm-button-danger" disabled={!!busy} onClick={() => void run("kill-switch", async () => { await request("/api/stm-hunt/trade", { action: "kill-switch", active: true }); await refresh(); setMessage("紧急停机已请求，新的 CEX 执行将被阻止。请核对现有持仓。"); })}><ShieldX size={14} />启用紧急停机</button><button type="button" className="stm-button stm-button-ghost" disabled={!!busy} onClick={() => void run("reconcile", async () => { await request("/api/stm-hunt/trade", { action: "reconcile", venue: "cex" }); await refresh(); setMessage("CEX 订单与仓位对账已完成。"); })}><RefreshCw size={14} />核对 CEX 成交与仓位</button></section><section className="stm-panel stm-account-equity"><PanelHeading eyebrow="ACCOUNT EQUITY" title="账户资产与风险" />{entries(cex.portfolioStats).length ? entries(cex.portfolioStats).map((stats, index) => <div key={`${text(stats.environment)}-${text(stats.market)}-${index}`}><span><Badge tone={stats.environment === "live" ? "pink" : "purple"}>{text(stats.environment).toUpperCase()}</Badge> {text(stats.market).toUpperCase()}</span><strong>{money(typeof stats.equity === "number" ? stats.equity : null)}</strong><dl><dt>持仓风险敞口</dt><dd>{money(typeof stats.riskExposureNotional === "number" ? stats.riskExposureNotional : null)}</dd><dt>未实现盈亏</dt><dd>{money(typeof stats.unrealizedPnl === "number" ? stats.unrealizedPnl : null)}</dd><dt>交易所已实现盈亏</dt><dd>{money(typeof stats.historicalRealizedPnl === "number" ? stats.historicalRealizedPnl : null)}</dd></dl><small>更新 {date(text(stats.refreshedAt, ""))}</small></div>) : <p>预检账户后显示交易所核实的资产数据。未提供的数据保留为未知。</p>}{Array.isArray(overview?.notes) ? <div className="stm-trade-notes">{overview.notes.map((note, index) => <p key={index}>{text(note)}</p>)}</div> : null}</section><WalletOrderHistory overview={overview} busy={!!busy} onAction={(body) => void run("wallet-history", async () => { const result = await request<Json>("/api/stm-hunt/trade", body); await refresh(); setMessage(result.final ? `链上最终状态：${text(result.status)}` : result.status ? `当前链上状态：${text(result.status)}，请继续对账确认。` : "交易记录已更新。"); })} /><section className="stm-panel stm-execution-history"><PanelHeading eyebrow="ORDERS & POSITIONS" title="交易记录" />{entries(cex.orders).length ? entries(cex.orders).slice(0, 15).map((order, index) => <div key={text(order.id, String(index))}><strong>{text(order.symbol)} <Badge tone="cyan">{text(order.state ?? order.status)}</Badge></strong><p>{text(order.side)} · {text(order.environment ?? order.mode)} · 数量 {text(order.quantity)}</p><small>{date(text(order.createdAt, ""))}</small></div>) : <Empty title="暂无订单记录" detail="执行后在这里查看记录，并通过成交对账更新实际状态。" />}{entries(cex.positions).length ? <><h3>持仓</h3>{entries(cex.positions).slice(0, 10).map((position, index) => <div key={text(position.id, String(index))}><strong>{text(position.symbol)}</strong><p>{text(position.side)} · {text(position.quantity)} · {text(position.state ?? position.status)}</p><PositionActions position={position} busy={!!busy} onAction={(body) => void run("position", async () => { await request("/api/stm-hunt/trade", body); await refresh(); setMessage("持仓操作已处理，请核对最新订单与保护状态。"); })} /></div>)}</> : null}</section></aside></div>;
}

function WalletGroups() {
  const [wallets, setWallets] = useState<Json[]>([]);
  const [chain, setChain] = useState("bsc");
  const [address, setAddress] = useState("");
  const [label, setLabel] = useState("");
  const [group, setGroup] = useState("我的观察组");
  const [vetted, setVetted] = useState(false);
  const [clusterId, setClusterId] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [message, setMessage] = useState<string | null>(null);
  const refresh = useCallback(async (signal?: AbortSignal) => {
    const result = await request<{ wallets: Json[] }>("/api/stm-hunt/wallets", undefined, signal);
    setWallets(result.wallets);
  }, []);
  useEffect(() => { const controller = new AbortController(); void refresh(controller.signal).catch((caught) => { if (!controller.signal.aborted) setError(caught instanceof Error ? caught.message : "地址组暂不可用"); }); return () => controller.abort(); }, [refresh]);
  async function save(body: Json) {
    setBusy(true); setError(null); setMessage(null);
    try { await request("/api/stm-hunt/wallets", body); await refresh(); setMessage(body.action === "remove" ? "地址已移除。" : "监控地址已保存。未审核地址仅用于观察。"); if (body.action === "save") { setAddress(""); setLabel(""); } }
    catch (caught) { setError(caught instanceof Error ? caught.message : "地址组操作失败"); }
    finally { setBusy(false); }
  }
  return <section className="stm-panel stm-wallet-groups"><PanelHeading eyebrow="ONCHAIN WATCH GROUPS" title="链上地址监控组"><Badge>{wallets.length}/500</Badge></PanelHeading>{error ? <div className="stm-message stm-message-error" role="alert"><CircleAlert size={14} /><span>{error}</span></div> : null}{message ? <p className="stm-wallet-message" role="status">{message}</p> : null}<form onSubmit={(event) => { event.preventDefault(); void save({ action: "save", chain, address, label, group, ...(vetted ? { vetted, clusterId } : {}) }); }}><div className="stm-form-grid"><label>链<select value={chain} onChange={(event) => setChain(event.target.value)}><option value="bsc">BNB Smart Chain</option><option value="solana">Solana</option><option value="ethereum">Ethereum</option><option value="base">Base</option></select></label><label>监控组<input required value={group} maxLength={60} onChange={(event) => setGroup(event.target.value)} /></label><label className="stm-field-full">钱包地址<input value={address} minLength={20} maxLength={64} required placeholder={chain === "solana" ? "Solana 公开钱包地址" : "0x…公开钱包地址"} onChange={(event) => setAddress(event.target.value)} /></label><label className="stm-field-full">地址标签<input value={label} maxLength={80} placeholder="交易员名称 / 研究备注" onChange={(event) => setLabel(event.target.value)} /></label></div><details className="stm-wallet-review"><summary>管理员：独立实体审核</summary><p>只有管理员通过 2FA 后才能将地址纳入已审核策略集合。关联资金地址必须使用相同的实体组号。</p><label className="stm-checkbox"><input type="checkbox" checked={vetted} onChange={(event) => setVetted(event.target.checked)} /><span>已独立核验该地址与资金关联</span></label>{vetted ? <label>实体 / 资金关联组<input required minLength={3} maxLength={120} value={clusterId} placeholder="相同控制人的地址使用相同组号" onChange={(event) => setClusterId(event.target.value)} /></label> : null}</details><button type="submit" className="stm-button stm-button-primary" disabled={busy}><Radar size={14} />保存监控地址</button></form><div className="stm-wallet-group-list">{wallets.length ? wallets.map((wallet) => <div key={text(wallet.id)}><span><strong>{text(wallet.label, "未命名地址") || "未命名地址"}</strong><small>{text(wallet.chain).toUpperCase()} · {shortAddress(text(wallet.address))}</small><small>{text(wallet.group)} {wallet.qualified ? "· 已审核实体" : "· 观察地址"}</small></span><button type="button" aria-label={`移除地址 ${text(wallet.address)}`} disabled={busy} onClick={() => void save({ action: "remove", chain: wallet.chain, address: wallet.address, label: text(wallet.label, ""), group: text(wallet.group, "我的观察组"), ...(wallet.qualified ? { vetted: true } : {}) })}><X size={14} /></button></div>) : <p>添加公开钱包地址，为解码事件与地址聚类建立观察集合。</p>}</div></section>;
}

function PositionActions({ position, busy, onAction }: { position: Json; busy: boolean; onAction: (body: Json) => void }) {
  const [review, setReview] = useState(false);
  const [confirmed, setConfirmed] = useState(false);
  const [stop, setStop] = useState(text(position.stopLoss, ""));
  const [take, setTake] = useState(text(position.takeProfit, ""));
  if (["CLOSED", "closed"].includes(text(position.state ?? position.status)) || !text(record(record(position.plan).intent).source, "").startsWith("stm-hunt:")) return null;
  return <div className="stm-position-actions"><button type="button" className="stm-button stm-button-small stm-button-ghost" onClick={() => { setReview(!review); setConfirmed(false); }}>管理持仓</button>{review ? <div><label>止损价<input type="number" min="0.00000001" step="any" value={stop} onChange={(event) => { setStop(event.target.value); setConfirmed(false); }} /></label><label>止盈价<input type="number" min="0.00000001" step="any" value={take} onChange={(event) => { setTake(event.target.value); setConfirmed(false); }} /></label><label className="stm-checkbox"><input type="checkbox" checked={confirmed} onChange={(event) => setConfirmed(event.target.checked)} /><span>确认对该持仓执行所选操作，实盘将影响真实资金。</span></label><button type="button" className="stm-button stm-button-small stm-button-ghost" disabled={busy || !confirmed || !(Number(stop) > 0) || !(Number(take) > 0)} onClick={() => { onAction({ action: "protection", positionId: position.id, stopLoss: Number(stop), takeProfit: Number(take), confirmation: "CONFIRM_STM_POSITION_ACTION" }); setConfirmed(false); }}>更新止盈止损</button><button type="button" className="stm-button stm-button-small stm-button-danger" disabled={busy || !confirmed} onClick={() => { onAction({ action: "close-position", positionId: position.id, confirmation: "CONFIRM_STM_POSITION_ACTION" }); setConfirmed(false); }}>确认平仓</button></div> : null}</div>;
}

function WalletOrderHistory({ overview, busy, onAction }: { overview: Json | null; busy: boolean; onAction: (body: Json) => void }) {
  const [recoverId, setRecoverId] = useState<string | null>(null);
  const [hash, setHash] = useState("");
  const [confirmed, setConfirmed] = useState(false);
  const quotes = entries(overview?.quotes);
  return <section className="stm-panel stm-wallet-orders"><PanelHeading eyebrow="BSC SETTLEMENT" title="链上订单与恢复"><Badge>{quotes.length} ORDERS</Badge></PanelHeading>{quotes.length ? quotes.slice(0, 20).map((quote) => <article key={text(quote.quoteId)}><div><strong>{text(quote.symbol)} <span>{text(quote.side) === "buy" ? "买入" : "卖出"}</span></strong><Badge tone={quote.status === "CONFIRMED" ? "green" : ["REVERTED", "MISMATCH"].includes(text(quote.status)) ? "pink" : "yellow"}>{text(quote.status)}</Badge></div><p>{money(typeof quote.notionalUsd === "number" ? quote.notionalUsd : null)} · {shortAddress(text(quote.walletAddress))}</p><small>{date(quote.createdAt as number)} · {shortAddress(text(quote.quoteId))}</small>{quote.txHash ? <a href={`https://bscscan.com/tx/${text(quote.txHash)}`} target="_blank" rel="noreferrer">{shortAddress(text(quote.txHash))} <ExternalLink size={11} /></a> : null}<div className="stm-wallet-order-actions">{quote.txHash ? <button type="button" className="stm-button stm-button-small stm-button-ghost" disabled={busy} onClick={() => onAction({ action: "reconcile", venue: "bsc", quoteId: quote.quoteId, address: quote.walletAddress })}>重新对账</button> : quote.status === "QUOTED" ? <button type="button" className="stm-button stm-button-small stm-button-ghost" disabled={busy} onClick={() => { setRecoverId(recoverId === quote.quoteId ? null : text(quote.quoteId)); setHash(""); setConfirmed(false); }}>恢复广播登记</button> : null}</div>{recoverId === quote.quoteId ? <form onSubmit={(event) => { event.preventDefault(); onAction({ action: "submit", quoteId: quote.quoteId, address: quote.walletAddress, txHash: hash, confirmation: "CONFIRM_STM_BSC_TRADE" }); setRecoverId(null); setConfirmed(false); }}><p>仅当钱包已成功广播此报价，但页面未完成登记时使用。核对交易哈希后登记，不会再次发送 Swap。</p><input aria-label="已广播的 BSC 交易哈希" placeholder="0x…64 位交易哈希" pattern="0x[0-9a-fA-F]{64}" value={hash} onChange={(event) => { setHash(event.target.value); setConfirmed(false); }} required /><label className="stm-checkbox"><input type="checkbox" checked={confirmed} onChange={(event) => setConfirmed(event.target.checked)} /><span>确认该哈希属于此报价与钱包。</span></label><button type="submit" className="stm-button stm-button-small stm-button-primary" disabled={busy || !confirmed}>登记已广播交易</button></form> : null}{quote.status === "CONFIRMED" ? <p className="stm-wallet-fill">实际付出 {text(quote.actualInput)} · 实际收到 {text(quote.actualOutput)}<br />Gas {text(quote.gasFeeBnb)} BNB</p> : null}</article>) : <Empty title="暂无链上订单" detail="报价、广播与最终结算分别记录；交易成功需验证转账并达到三次确认。" />}</section>;
}

function PlanDetails({ plan }: { plan: Json }) {
  const value = Object.keys(record(plan.executionPlan)).length ? record(plan.executionPlan) : Object.keys(record(plan.plan)).length ? record(plan.plan) : plan;
  const order = record(value.mainOrder);
  const risk = record(value.risk);
  const safeguards = record(value.safeguards);
  const fields = ["planId", "id", "mode", "symbol", "side", "quantity", "notionalUsd", "entryPrice", "stopLoss", "takeProfit", "riskPct", "status", "expiresAt"];
  const labels: Record<string, string> = { planId: "计划编号", id: "计划编号", mode: "执行模式", symbol: "交易对", side: "方向", quantity: "数量", notionalUsd: "名义金额", entryPrice: "参考入场", stopLoss: "止损", takeProfit: "止盈", riskPct: "风险预算 %", status: "状态", expiresAt: "有效至" };
  return <><dl>{fields.filter((key) => value[key] != null).map((key) => <div key={key}><dt>{labels[key]}</dt><dd>{key === "expiresAt" ? date(value[key] as string | number) : text(value[key])}</dd></div>)}{[...Object.entries(order).filter(([key]) => ["symbol", "side", "type", "quantity", "price"].includes(key)), ...Object.entries(risk).filter(([key]) => ["notional", "riskAmount", "marginRequired", "leverage", "riskPct"].includes(key))].map(([key, item]) => <div key={`order-${key}`}><dt>{({ symbol: "交易对", side: "订单方向", type: "订单类型", quantity: "下单数量", price: "委托参考价", notional: "名义金额", riskAmount: "风险金额", marginRequired: "所需保证金", leverage: "杠杆", riskPct: "风险预算 %" } as Record<string, string>)[key]}</dt><dd>{text(item)}</dd></div>)}</dl>{entries(value.protectionOrders).length ? <div className="stm-protection-preview"><h4>保护订单</h4>{entries(value.protectionOrders).map((item, index) => <p key={index}>{text(item.type)} · {text(item.side)} · 触发价 {text(item.stopPrice ?? item.triggerPrice ?? item.price)} · 数量 {text(item.quantity)}</p>)}</div> : null}{Object.keys(safeguards).length ? <details className="stm-plan-safeguards"><summary>查看执行保护参数</summary><pre>{JSON.stringify(safeguards, null, 2)}</pre></details> : null}{Array.isArray(value.reasons) ? <p>{value.reasons.join("；")}</p> : null}{plan.message ? <p>{text(plan.message)}</p> : null}</>;
}
